// Window organization without the top menu bar.
const topMenu=document.querySelector('header');if(topMenu)topMenu.remove();
const windowToolBar=document.createElement('div');windowToolBar.id='window-tools-menu';windowToolBar.hidden=true;windowToolBar.innerHTML='<div class="window-tools-heading">Acomodar ventanas</div><button data-windowmode="left">▌ Mitad izquierda</button><button data-windowmode="right">▐ Mitad derecha</button><button data-windowmode="maximize">□ Maximizar / restaurar</button><button data-windowmode="cascade">▱ En cascada</button><button data-windowmode="overview">▦ Ver apps abiertas</button>';document.body.append(windowToolBar);
let windowTarget=null;
function activeWindow(){return [...opened.values()].filter(w=>!w.hidden).sort((a,b)=>Number(b.style.zIndex)-Number(a.style.zIndex))[0]}
function setWindowMode(mode,w=activeWindow()){windowToolBar.hidden=true;if(mode==='overview'){showOverview();return}if(mode==='cascade'){let i=0;opened.forEach(win=>{win.hidden=false;win.classList.remove('maximized','snapped-window');win.style.left=(innerWidth<701?8:45+(i%7)*32)+'px';win.style.top=(18+(i%7)*27)+'px';if(win.dataset.restoreWidth){win.style.width=win.dataset.restoreWidth;win.style.height=win.dataset.restoreHeight}i++});tasks();return}if(!w){toast('Abre una app para acomodarla.');return}if(mode==='maximize'){w.classList.remove('snapped-window');w.classList.toggle('maximized');focus(w);return}if(!w.dataset.restoreWidth){w.dataset.restoreWidth=w.style.width;w.dataset.restoreHeight=w.style.height}w.classList.remove('maximized');w.classList.add('snapped-window');let available=innerHeight-62;if(innerWidth<650){w.style.left='8px';w.style.width=(innerWidth-16)+'px'}else{const half=Math.floor((innerWidth-24)/2);w.style.left=(mode==='left'?8:16+half)+'px';w.style.width=half+'px'}w.style.top='8px';w.style.height=available+'px';w.hidden=false;focus(w)}
function showWindowTools(w,button){windowTarget=w;const rect=button.getBoundingClientRect();windowToolBar.style.left=Math.max(8,Math.min(innerWidth-230,rect.right-220))+'px';windowToolBar.style.top=Math.min(innerHeight-230,rect.bottom+5)+'px';windowToolBar.hidden=false}
const windowToolsOpen=openApp;openApp=function(id){windowToolsOpen(id);const w=opened.get(id);if(!w||w.querySelector('.window-arrange'))return;const button=document.createElement('button');button.className='window-arrange';button.textContent='▦';button.title='Acomodar ventana';button.setAttribute('aria-label','Acomodar ventana');button.onclick=e=>{e.stopPropagation();showWindowTools(w,button)};w.querySelector('.titlebar').insertBefore(button,w.querySelector('.controls'));};
windowToolBar.onclick=e=>{const b=e.target.closest('[data-windowmode]');if(b)setWindowMode(b.dataset.windowmode,windowTarget)};
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#window-tools-menu,.window-arrange'))windowToolBar.hidden=true});
const overview=document.createElement('div');overview.id='window-overview';overview.hidden=true;overview.innerHTML='<section class="overview-panel" role="dialog" aria-modal="true" aria-label="Aplicaciones abiertas"><div class="overview-heading"><div><span>TU ESPACIO DE TRABAJO</span><h2>Todo a la vista.</h2></div><button id="closeoverview" aria-label="Cerrar vista de apps">×</button></div><div id="overview-grid"></div><p>Selecciona una app para volver a ella.</p></section>';document.body.append(overview);let overviewFocus=null;
function closeOverview(){overview.hidden=true;overviewFocus?.focus?.()}
function showOverview(){overviewFocus=document.activeElement;overview.hidden=false;const grid=overview.querySelector('#overview-grid');grid.replaceChildren();if(!opened.size){let p=document.createElement('p');p.textContent='Todavía no hay apps abiertas.';grid.append(p)}for(const [id,w] of opened){let card=document.createElement('button');card.className='overview-card';card.innerHTML=svg(id);let name=document.createElement('strong');name.textContent=apps[id][0];let state=document.createElement('small');state.textContent=w.hidden?'Minimizada':'Abierta';card.append(name,state);card.onclick=()=>{closeOverview();openApp(id)};grid.append(card)}overview.querySelector('button').focus()}
overview.querySelector('#closeoverview').onclick=closeOverview;overview.onclick=e=>{if(e.target===overview)closeOverview()};
const overviewButton=document.createElement('button');overviewButton.id='overviewbutton';overviewButton.textContent='▦';overviewButton.title='Ver apps abiertas · Ctrl + Alt + Tab';overviewButton.setAttribute('aria-label','Ver apps abiertas');overviewButton.onclick=showOverview;$('#tasks').before(overviewButton);
const arrangement=document.createElement('button');arrangement.textContent='▱ Acomodar ventanas';arrangement.onclick=()=>setWindowMode('cascade');$('#desktop-context').append(arrangement);const overviewContext=document.createElement('button');overviewContext.textContent='▦ Ver apps abiertas';overviewContext.onclick=showOverview;$('#desktop-context').append(overviewContext);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){windowToolBar.hidden=true;if(!overview.hidden)closeOverview()}if(e.ctrlKey&&e.altKey&&['ArrowLeft','ArrowRight','ArrowUp','Tab'].includes(e.key)){e.preventDefault();setWindowMode({ArrowLeft:'left',ArrowRight:'right',ArrowUp:'maximize',Tab:'overview'}[e.key])}if(!overview.hidden&&e.key==='Tab'){const items=[...overview.querySelectorAll('button')];let index=items.indexOf(document.activeElement);e.preventDefault();items[(index+(e.shiftKey?-1:1)+items.length)%items.length]?.focus()}},true);
